// Strategy: GenerateWithPrefixAndManagedSpan with explicit guidance to suppress
// {variable} notation (brace-wrapped template names) inside constrained
// spans. The parser rejects `{`, `}`, `$`, `**`. New guidance explicitly maps
// "{variable}" placeholders → bare variable names without braces, targeting
// malformed_constrained_content failures.
//
// Parameters:
//   prefixBudget = 78% of mainBudget (663/850), boostAmount = 8.0, narrowThreshold = 6.
//   mainBudget = maxSteps - 50 = 850. closeBudget = 50.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization branch:
//     Assigned directly from method parameters; the precondition
//     `insideConstrained ==> parser.IsValidPrefix(currentConstrained)` makes the
//     invariant hold at entry.
//
//   After GenerateWithPrefixAndManagedSpan:
//     The helper's postcondition directly guarantees
//     `!ic ==> cc == []` and `ic ==> parser.IsValidPrefix(cc)`.
//     We assign insideConstrainedOut := ic and currentConstrainedOut := cc, so
//     the invariant holds.
//
//   After CloseSpanWithinBudget (fallback branch):
//     This branch is entered only when insideConstrainedOut == true, which already
//     satisfies `parser.IsValidPrefix(currentConstrainedOut)` (the helper's
//     precondition). The helper's postcondition guarantees
//     `!ci ==> cc2 == []` and `ci ==> parser.IsValidPrefix(cc2)`.
//     We assign insideConstrainedOut := ci and currentConstrainedOut := cc2, so
//     the invariant holds after the fallback too.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + maxSteps   and   cost <= maxSteps
//
//   After GenerateWithPrefixAndManagedSpan(mainBudget):
//     Postcondition: |g| <= |generatedPrefix| + mainBudget.
//     Since mainBudget = maxSteps - 50, |g| <= |generatedPrefix| + maxSteps - 50.
//     Visible tokens consumed by the helper (including EOS, rejected suffixes, and
//     constrained tokens) are each charged one step internally, so output growth
//     is at most mainBudget even when EOS or rollback steps are taken.
//
//   After CloseSpanWithinBudget(closeBudget = 50):
//     Postcondition: |cg| <= |g| + closeBudget <= |generatedPrefix| + maxSteps - 50 + 50
//       = |generatedPrefix| + maxSteps. Checked.
//     Tokens consumed by closing (including the ">>" delimiter) are at most
//     closeBudget steps; visible growth cannot exceed that budget.
//
//   cost := maxSteps satisfies cost <= maxSteps. Checked.
//   When maxSteps > 0, cost = maxSteps > 0, satisfying the progress postcondition
//   `cost > 0` directly. Checked.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve step by step. The problem uses {variable} placeholders. In your final <<expr>>, write BARE variable names WITHOUT braces: write n not {n}, price not {price}, fraction not {fraction}, total not {total}. End with EXACTLY ONE <<expr>> using only: bare variable names, numbers, +, -, *, /, //, %, (, ), int(). Use // for integer division. Wrap integer results in int(). Examples: <<int(n * price)>>, <<int((total * frac) // rate)>>, <<w1 + w2 + w3>>. No LaTeX, no $, no {braces}, no **.";
  helpers.AppendTaskGuidance(lm, guidance);

  var mainBudget: nat := if maxSteps > 50 then maxSteps - 50 else maxSteps;
  var closeBudget: nat := if maxSteps > 50 then 50 else 0;
  var prefixBudget: nat := (mainBudget * 78) / 100;

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    mainBudget, prefixBudget, validTokenGroups, 8.0, 6, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  if insideConstrainedOut && closeBudget > 0 {
    var cg, ci, cc2 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc2;
  }

  cost := maxSteps;
}
